     @statictypes
    @mtproto_required
    @mutex
    async def leave_call(
        self,
        chat_id: int | str,
        close: bool = False,
    ):
        chat_id = await self.resolve_chat_id(chat_id)
        is_p2p_waiting = (
            chat_id in self._p2p_configs
            and not self._p2p_configs[chat_id].wait_data.done()
        )
        is_group = False
        if not is_p2p_waiting:
            try:
                is_group = await self._binding.get_call_type(chat_id) in (
                    CallType.GROUP,
                    CallType.CONFERENCE,
                )
                await self._binding.stop(chat_id)
            except ConnectionNotFound:
                raise NotInCallError()
        if is_group:
            input_call = await self._app.get_input_call(
                chat_id,
            )

            if input_call is None:
                raise NoActiveGroupCall()

            await self._app.leave_group_call(
                chat_id,
            )
        else:
            await self._app.discard_call(chat_id, False)
        if is_p2p_waiting:
            self._p2p_configs.pop(chat_id)
            return
        if is_group:
            self._clear_cache(chat_id)  # type: ignore

        if chat_id < 0 and close:  # type: ignore
            await self._app.close_voice_chat(chat_id)

